def handle(app, svc):
    resp = svc.apply(app)
    outcome = resp["result"]["outcome"]
    limit = resp["result"].get("credit_limit", 0)

    self_employed = app.get("employment") == "self_employed"
    high_limit = (app.get("requested_limit") or 0) > 7000

    if outcome == "declined":
        return {"action": "decline", "limit": 0}

    if outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}

    # outcome == approved
    if self_employed and high_limit:
        return {"action": "queue_review", "limit": 0}
    return {"action": "issue", "limit": limit}
